#pragma once

#include <algorithm>
#include <cmath>
#include <functional>
#include <memory>
#include <vector>
#include <velora/data/Observable.hpp>
#include <velora/globals.hpp>
#include <velora/runtime/Framework.hpp>

// Realizes the visible range of an ObservableVector into a ListView through a generated
// DataTemplate class, and recycles containers as they scroll out of view.
//
// Template is generated by velorac for each <DataTemplate>: it builds one container under a
// parent element and exposes `root()` and `bind(Item*)`. bind(nullptr) drops the container's
// subscriptions to its item, so a pooled container keeps no callbacks into any item, and a
// removed item is unbound before it is destroyed. Each container's handlers act on the item
// it is bound to at the time.
namespace velora
{

template <class Item, class Template> class ItemsRepeater
{
public:
    using Factory = std::function<std::unique_ptr<Template>(ElementId parent)>;
    static constexpr std::size_t kMaxPool = 8;

    ItemsRepeater(Framework& ui, ElementId list, Factory factory)
        : m_ui(ui), m_list(list), m_factory(std::move(factory))
    {
        m_ui.onViewport(m_list, [this] { realize(); });
    }
    ~ItemsRepeater()
    {
        if (m_ui.tree().contains(m_list))
            m_ui.onViewport(m_list, {});
    }
    ItemsRepeater(const ItemsRepeater&) = delete;
    ItemsRepeater& operator=(const ItemsRepeater&) = delete;

    void setSource(ObservableVector<Item>* source)
    {
        if (source == m_source)
            return;
        recycleAll();
        m_source = source;
        m_subscription =
            m_source ? m_source->subscribe([this](const VectorChange& c) { changed(c); }) : Subscription{};
        countChanged();
        realize();
    }

    std::size_t realizedCount() const noexcept
    {
        return m_realized.size();
    }
    std::size_t pooledCount() const noexcept
    {
        return m_pool.size();
    }
    // The container showing item `index`, if it is realized.
    Template* container(std::size_t index) const
    {
        for (const auto& slot : m_realized)
            if (slot.index == index)
                return slot.view.get();
        return nullptr;
    }

private:
    struct Slot
    {
        std::unique_ptr<Template> view;
        std::size_t index;
    };

    void changed(const VectorChange& c)
    {
        using Kind = VectorChange::Kind;
        if (c.kind == Kind::kReset)
        {
            recycleAll();
        }
        else
        {
            for (std::size_t i = 0; i < m_realized.size();)
            {
                auto& slot = m_realized[i];
                if (c.kind == Kind::kRemoved && slot.index == c.index)
                {
                    recycle(i); // unbinds while the removed item is still alive
                    continue;
                }
                if (c.kind == Kind::kReplaced && slot.index == c.index)
                    slot.view->bind(&(*m_source)[c.index]);
                if (c.kind == Kind::kInserted && slot.index >= c.index)
                    place(slot, slot.index + 1);
                if (c.kind == Kind::kRemoved && slot.index > c.index)
                    place(slot, slot.index - 1);
                ++i;
            }
        }
        countChanged();
        realize();
    }

    void countChanged()
    {
        m_ui.set(m_list, m_ui.props().ItemCount,
                 PropertyValue(static_cast<i64>(m_source ? m_source->size() : 0)));
    }

    // Binds containers to the items in the last known viewport and pools the rest.
    void realize()
    {
        const auto v = m_ui.viewport(m_list);
        std::size_t first = 0, last = 0;
        if (m_source && v.itemHeight > 0 && v.height > 0)
        {
            first = static_cast<std::size_t>(std::floor(v.offset / v.itemHeight));
            last = std::min(m_source->size(),
                            static_cast<std::size_t>(std::ceil((v.offset + v.height) / v.itemHeight)));
        }
        for (std::size_t i = 0; i < m_realized.size();)
        {
            if (m_realized[i].index < first || m_realized[i].index >= last ||
                m_realized[i].index >= sourceSize())
                recycle(i);
            else
                ++i;
        }
        for (std::size_t index = first; index < last; ++index)
        {
            if (container(index))
                continue;
            std::unique_ptr<Template> view;
            if (!m_pool.empty())
            {
                view = std::move(m_pool.back());
                m_pool.pop_back();
            }
            else
            {
                view = m_factory(m_list);
            }
            m_ui.set(view->root(), m_ui.props().Visibility, PropertyValue(true));
            view->bind(&(*m_source)[index]);
            m_realized.push_back({std::move(view), index});
            place(m_realized.back(), index);
        }
        while (m_pool.size() > kMaxPool)
            m_pool.pop_back(); // a container's destructor removes its elements
    }

    void place(Slot& slot, std::size_t index)
    {
        slot.index = index;
        m_ui.set(slot.view->root(), m_ui.props().ItemIndex, PropertyValue(static_cast<i64>(index)));
    }

    void recycle(std::size_t position)
    {
        auto view = std::move(m_realized[position].view);
        m_realized.erase(m_realized.begin() + static_cast<std::ptrdiff_t>(position));
        view->bind(nullptr);
        m_ui.set(view->root(), m_ui.props().Visibility, PropertyValue(false));
        m_pool.push_back(std::move(view));
    }

    void recycleAll()
    {
        while (!m_realized.empty())
            recycle(m_realized.size() - 1);
    }

    std::size_t sourceSize() const noexcept
    {
        return m_source ? m_source->size() : 0;
    }

    Framework& m_ui;
    ElementId m_list;
    Factory m_factory;
    ObservableVector<Item>* m_source = nullptr;
    Subscription m_subscription;
    std::vector<Slot> m_realized;
    std::vector<std::unique_ptr<Template>> m_pool;
};

} // namespace velora
